import biscuit_auth
from cappo_backend.security.biscuit import get_root_key_pair, AuthorizerBuilder
token_b64 = '-DR1AYKBBoCCAISJAgAEiDPpExOcMq7DOOzkevsm7hTkrUm8SI_PMsIrXGlaACEwxpAhispOmCJZxt5RPMDCuEiUKVh_2E_-N4wf9K8PF94Z3Ra_ACrAtIXxRmU10HAs7ac6ROJLqjs43YAeFhWyVwTAyIiCiCvk_M9c_J0bVoOuKPpCoB1rYe9grvPw7qkswiy1b3fvA=='
kp = get_root_key_pair()
token = biscuit_auth.Biscuit.from_base64(token_b64, kp.public_key)
auth_builder = AuthorizerBuilder()
auth_builder.add_code('allow if true;')
auth = auth_builder.build(token)
try:
    auth.authorize()
except Exception as e:
    print('Auth Error:', e)
exec_id_facts = auth.query(biscuit_auth.Rule('rule() <- execution_id()'))
print('exec_id_facts:', exec_id_facts)

